  // ---- DISC: hitung Graph I (tally Sangat), Graph II (tally Kurang), Graph III (I-II) ----
  // picks = [{no, sangat:"D"/"I"/"S"/"C", kurang:"D"/"I"/"S"/"C"}, ...] (idealnya 28 entri, 1 per grup)
  function computeDiscGraphs(picks) {
    const g1 = { D:0, I:0, S:0, C:0 }, g2 = { D:0, I:0, S:0, C:0 };
    (picks || []).forEach(p => {
      if (p.sangat && g1[p.sangat] != null) g1[p.sangat]++;
      if (p.kurang && g2[p.kurang] != null) g2[p.kurang]++;
    });
    const g3 = { D: g1.D - g2.D, I: g1.I - g2.I, S: g1.S - g2.S, C: g1.C - g2.C };
    return { graph1:g1, graph2:g2, graph3:g3 };
  }
  function discComplete(picks) {
    return Array.isArray(picks) && picks.length === DISC_GROUPS.length &&
      picks.every(p => p && p.sangat && p.kurang);
  }

  // ---- SSD: total per kategori (7 kategori x 5 soal, skor -3..+3 per soal) ----
  // answers = {"1":"STS", "2":"SS", ...} (key = no soal string, value = kode skala)
  function computeSsdScores(answers) {
    const scoreOf = code => { const s = SSD_SCALE.find(o => o.code === code); return s ? s.score : 0; };
    const scores = {};
    SSD_CATEGORIES.forEach(cat => {
      scores[cat.code] = cat.questions.reduce((sum, no) => sum + scoreOf((answers || {})[String(no)]), 0);
    });
    return scores;
  }
  function ssdComplete(answers) {
    answers = answers || {};
    return SSD_QUESTIONS.every(q => !!answers[String(q.no)]);
  }

  // ---- Karunia Rohani: total per karunia (17 karunia x 5 soal, skor 0-3 per soal) ----
  // answers = {"1":3, "2":0, ...} (key = no soal string, value = angka 0-3)
  function computeGiftsScores(answers) {
    answers = answers || {};
    const scores = {};
    GIFTS_LIST.forEach(g => {
      scores[g.code] = g.questions.reduce((sum, no) => sum + (Number(answers[String(no)]) || 0), 0);
    });
    const ranked = GIFTS_LIST.map(g => g.code).sort((a, b) => scores[b] - scores[a]);
    // 2026-09-23 (permintaan user, "Karunia Rohani adalah bagian dari
    // Strength"): pengelompokan disesuaikan dgn lembar asli JB3 SERVE
    // ROADMAP (image referensi) — peringkat 1-3 = "Paling Menonjol",
    // peringkat 4-6 = "Cukup Menonjol". SEBELUMNYA field ini bernama
    // "bottom3" dan isinya 3 PALING RENDAH (kebalikannya) — itu salah,
    // sekarang diganti "next3" (posisi 4-6, bukan yg paling rendah).
    return { scores, top3: ranked.slice(0, 3), next3: ranked.slice(3, 6) };
  }
  function giftsComplete(answers) {
    answers = answers || {};
    return GIFTS_QUESTIONS.every(q => answers[String(q.no)] !== undefined && answers[String(q.no)] !== null && answers[String(q.no)] !== "");
  }

  function giftName(code) { const g = GIFTS_LIST.find(x => x.code === code); return g ? g.name : code; }
  function ssdCatName(code) { const c = SSD_CATEGORIES.find(x => x.code === code); return c ? c.name : code; }

